import java.io.*;
import java.util.*;

public class Main {
    static final int mod = 1000000007;
    static final int N = (1 << 20) + 5;
    static int n, lim, ans;
    static int[] p1 = new int[N], p2 = new int[N];
    static int[][] flag = new int[10][10];
    static int[][][] a = new int[10][10][10];
    static int[][][] h = new int[10][10][10];

    static int fpow(int x, int y) {
        int res = 1;
        while (y > 0) {
            if ((y & 1) == 1) res = (int) ((long) res * x % mod);
            x = (int) ((long) x * x % mod);
            y >>= 1;
        }
        return res;
    }

    static int inv(int x) {
        return fpow(x, mod - 2);
    }

    static boolean check(int x, int y, int z) {
        int[] a = new int[]{x, y, z};
        int[] d = new int[]{0, 1, 2};
        do {
            if (flag[a[d[0]]][1] != 0 && flag[a[d[1]]][2] != 0 && flag[a[d[2]]][3] != 0) return true;
        } while (nextPermutation(d));
        return false;
    }

    static void dfs1(int P, int x, int y) {
        if (x == 7 && y == 1) {
            int sta = 0;
            for (int i = 1; i <= 6; i++)
                for (int j = i + 1; j <= 6; j++)
                    for (int k = j + 1; k <= 6; k++) {
                        if (check(i, j, k)) {
                            int x1 = 1;
                            while (x1 == i || x1 == j || x1 == k) x1++;
                            int y1 = x1 + 1;
                            while (y1 == i || y1 == j || y1 == k) y1++;
                            int z = y1 + 1;
                            while (z == i || z == j || z == k) z++;
                            sta |= h[x1][y1][z];
                        }
                    }
            p1[sta] = (p1[sta] + P) % mod;
            return;
        }
        flag[x][y] = 1;
        if (y == 3) dfs1((int) ((long) P * a[x][y] % mod), x + 1, 1);
        else dfs1((int) ((long) P * a[x][y] % mod), x, y + 1);
        flag[x][y] = 0;
        if (y == 3) dfs1((int) ((long) P * (mod + 1 - a[x][y]) % mod), x + 1, 1);
        else dfs1((int) ((long) P * (mod + 1 - a[x][y]) % mod), x, y + 1);
    }

    static void dfs2(int P, int x, int y) {
        if (x == 7 && y == 4) {
            int sta = 0;
            for (int i = 1; i <= 6; i++)
                for (int j = i + 1; j <= 6; j++)
                    for (int k = j + 1; k <= 6; k++) {
                        if (check(i, j, k)) sta |= h[i][j][k];
                    }
            p2[sta] = (p2[sta] + P) % mod;
            ans = (ans + (int) ((long) p1[lim ^ sta] * P % mod)) % mod;
            return;
        }
        flag[x][y - 3] = 1;
        if (y == 6) dfs2((int) ((long) P * a[x][y] % mod), x + 1, 4);
        else dfs2((int) ((long) P * a[x][y] % mod), x, y + 1);
        flag[x][y - 3] = 0;
        if (y == 6) dfs2((int) ((long) P * (mod + 1 - a[x][y]) % mod), x + 1, 4);
        else dfs2((int) ((long) P * (mod + 1 - a[x][y]) % mod), x, y + 1);
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= n; j++)
                a[i][j][1] = sc.nextInt();
        for (int i = n + 1; i <= 6; i++)
            for (int j = i; j <= 6; j++)
                a[i][j][1] = 1;
        int tot = 0;
        for (int i = 1; i <= 6; i++)
            for (int j = i + 1; j <= 6; j++)
                for (int k = j + 1; k <= 6; k++) {
                    h[i][j][k] = 1 << tot;
                    tot++;
                }
        dfs1(1, 1, 1);
        lim = (1 << 20) - 1;
        for (int i = 0; i <= 19; i++)
            for (int j = 0; j <= lim; j++)
                if ((j >> i & 1) == 1) p1[j] = (p1[j] + p1[j ^ 1 << i]) % mod;
        dfs2(1, 1, 4);
        ans = (mod + 1 - ans) % mod;
        System.out.println(ans);
    }

    static boolean nextPermutation(int[] array) {
        int n = array.length;
        int i = n - 2;
        while (i >= 0 && array[i] >= array[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (array[j] <= array[i]) j--;
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
        int left = i + 1, right = n - 1;
        while (left < right) {
            temp = array[left];
            array[left] = array[right];
            array[right] = temp;
            left++;
            right--;
        }
        return true;
    }
}
